  {
    "Name": "LogStream",
    "Key": "Core",
    "ResourceKey": "Core",
    "Script": "LogStream = {
    init: async function(app, container) {
        container = container || $(".component[name=LogStream]");
        if (typeof signalR === "undefined") {
            $("[name=logConsole]", container).append("<div class='message warn'>SignalR client is not loaded.</div>");
            return;
        }
        $("[name=level]", container).on("change", () => LogStream.applyLevelFilter(container));
        await LogStream.connectToLogHub(container);
    },

    connectToLogHub: async function(container) {
        var host = window.location.hostname.split(":")[0];
        await LogStream.connectToHub(container, function(connection) {
            connection.invoke("join", host);
            connection.invoke("ConsoleSend", "info", "Client Connected to Log Stream ", host);
        });
    },

    connectToHub: async function(container, callback) {
        var connection = new signalR.HubConnectionBuilder().withUrl(session.apiRoot + "Hubs/Logs").build();
        connection.on("ConsoleReceive", function(level, message) { LogStream.receiveMessage(container, level, message); });
        await connection.start();
        callback(connection);
    },

    normaliseLevel: function(level) {
        level = (level || "info").toLowerCase();
        if (level === "information") return "info";
        if (level === "warning") return "warn";
        if (level === "critical") return "fatal";
        return level;
    },

    selectedLevels: function(container) {
        return $("[name=level]:checked", container).map(function() { return this.value; }).get();
    },

    applyLevelFilter: function(container) {
        var selected = LogStream.selectedLevels(container);
        $(".execConsole > .console > .message", container).each(function() {
            $(this).toggle(selected.indexOf($(this).data("level")) >= 0);
        });
    },

    receiveMessage: function(container, level, message) {
        var entry = { Level: LogStream.normaliseLevel(level), Timestamp: new Date(), Message: message };
        var htmlConsole = $(".execConsole > .console", container);
        var row = $(LogStream.buildMessage(entry));
        row.toggle(LogStream.selectedLevels(container).indexOf(entry.Level) >= 0);
        htmlConsole.append(row);
        if ($("input[name=autoScroll]", container).is(":checked")) {
            htmlConsole.scrollTop(htmlConsole.prop("scrollHeight"));
        }
    },

    buildMessage: function(logEntry) {
        var time = new Date(logEntry.Timestamp);
        var encoded = $("<div />").text(logEntry.Message).html();
        return "<div class='message " + logEntry.Level + "' data-level='" + logEntry.Level + "'>" +
            "<span class='level'>" + logEntry.Level.toUpperCase() + "</span>" +
            "<span class='time'>" + time.toLocaleTimeString() + "</span>" +
            "<pre class='message'>" + encoded + "</pre></div>";
    }
};",
    "Content": "<div class="toolbar">
    <strong>Levels</strong>
    <label><input name="level" value="trace" type="checkbox" checked /> Trace</label>
    <label><input name="level" value="debug" type="checkbox" /> Debug</label>
    <label><input name="level" value="info" type="checkbox" checked /> Information</label>
    <label><input name="level" value="warn" type="checkbox" checked /> Warning</label>
    <label><input name="level" value="error" type="checkbox" checked /> Error</label>
    <label><input name="level" value="fatal" type="checkbox" checked /> Fatal</label>
    <label class="auto-scroll"><input name="autoScroll" type="checkbox" checked /> Auto Scroll</label>
</div>
<div class="execConsole" name="execConsole"><div class="console" name="logConsole"></div></div>
<style scoped>
    .component[name=LogStream] { display:flex; flex-direction:column; min-height:0; height:100%; }
    .component[name=LogStream] .toolbar { display:flex; flex-wrap:wrap; align-items:center; gap:.75rem; width:100%; background:#f3f6f9; padding:.65rem .8rem; border:1px solid #d7e0e8; }
    .component[name=LogStream] .toolbar label { display:inline-flex; align-items:center; gap:.3rem; margin:0; }
    .component[name=LogStream] .toolbar .auto-scroll { margin-left:auto; }
    .component[name=LogStream] .execConsole { flex:1 1 auto; min-height:0; }
    .component[name=LogStream] .execConsole > .console { padding:.6rem; height:100%; min-height:24rem; overflow:auto; border:1px solid #d7e0e8; background:#fff; }
    .component[name=LogStream] .message { line-height:1.35; }
    .component[name=LogStream] .message > * { vertical-align:top; margin:0; padding:1px; }
    .component[name=LogStream] .message > .message { display:inline-block; border:0; max-width:calc(100% - 10rem); white-space:pre-wrap; overflow-wrap:anywhere; }
    .component[name=LogStream] .level { display:inline-block; margin-right:.75rem; min-width:5.5rem; font-weight:600; }
    .component[name=LogStream] .time { display:inline-block; margin-right:.75rem; }
    .component[name=LogStream] .trace { color:#657786; }
    .component[name=LogStream] .info { color:#237a3b; }
    .component[name=LogStream] .debug { color:#245ac4; }
    .component[name=LogStream] .warn { color:#9a7100; }
    .component[name=LogStream] .error, .component[name=LogStream] .fatal { color:#b42318; }
</style>",
